get_dashboard_kpi_options.code:
use WebCommander\Resources\DashboardKpis\DashboardKpis;

$response = DashboardKpis::getDashboardKpiOptions($client);

echo 'Choose ', $response->map['min'], ' to ', $response->map['max'], ' of:', PHP_EOL;
foreach ($response->map['groups'] as $group) {
    foreach ($group['metrics'] as $metric) {
        echo $group['label'], ' ', $metric['key'], ' ', $metric['label'], PHP_EOL;
    }
}
